from math import prod

def isprime(x):
    if x < 2:
        return False
    d = 2
    while d*d <= x:
        if x % d == 0:
            return False
        d += 1
    return True

n=10
A=[[0]*n for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        if isprime(i^j):
            A[i][j]=A[j][i]=1

L=[[0]*n for _ in range(n)]
for i in range(n):
    deg=sum(A[i])
    L[i][i]=deg
    for j in range(n):
        if i!=j and A[i][j]:
            L[i][j]=-1

# Bareiss algorithm for exact determinant
M=[row[:-1] for row in L[:-1]]

def det_bareiss(mat):
    A=[row[:] for row in mat]
    n=len(A)
    sign=1
    prev=1
    for k in range(n-1):
        if A[k][k]==0:
            swap=None
            for i in range(k+1,n):
                if A[i][k]!=0:
                    swap=i
                    break
            if swap is None:
                return 0
            A[k],A[swap]=A[swap],A[k]
            sign*=-1
        pivot=A[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n):
                A[i][j]=(A[i][j]*pivot - A[i][k]*A[k][j])//prev
        prev=pivot
        for i in range(k+1,n):
            A[i][k]=0
        for j in range(k+1,n):
            A[k][j]=0
    return sign*A[n-1][n-1]

print('adjacency')
for row in A:
    print(row)
print('det', det_bareiss(M))
PY

