#include <bits/stdc++.h>
using namespace std;
int main(){
    const int n=40;
    const int m=n-1; // elements 2..40
    const int MOD=1000000007;
    vector<unsigned long long> prereq(m,0);
    vector<int> elems;
    for(int x=2;x<=n;x++) elems.push_back(x);
    unordered_map<int,int> idx;
    for(int i=0;i<m;i++) idx[elems[i]]=i;
    for(int i=0;i<m;i++){
        int x=elems[i];
        unsigned long long mask=0;
        for(int d=2; d<x; d++) if(x%d==0){
            auto it=idx.find(d);
            if(it!=idx.end()) mask |= 1ULL<<it->second;
        }
        prereq[i]=mask;
    }
    unordered_map<unsigned long long,int> cur, nxt;
    cur.reserve(1024); cur[0]=1;
    for(int lvl=0; lvl<m; lvl++){
        nxt.clear();
        nxt.reserve(cur.size()*2 + 1024);
        for(auto &kv: cur){
            unsigned long long mask=kv.first;
            int ways=kv.second;
            for(int i=0;i<m;i++){
                unsigned long long bit=1ULL<<i;
                if(mask & bit) continue;
                if((prereq[i] & mask) == prereq[i]){
                    auto &ref = nxt[mask|bit];
                    int nv = ref + ways;
                    if(nv>=MOD) nv-=MOD;
                    ref = nv;
                }
            }
        }
        cur.swap(nxt);
        cerr << "level " << lvl+1 << " states " << cur.size() << "\n";
    }
    unsigned long long full=(1ULL<<m)-1;
    cout << cur[full] << "\n";
}
