#include <bits/stdc++.h>
using namespace std;
static const int MOD=1000000007;
int addmod(int a,int b){ a+=b; if(a>=MOD) a-=MOD; return a; }
int main(){
    vector<array<int,3>> states;
    int idx[6][6][6];
    memset(idx,-1,sizeof(idx));
    for(int a=0;a<6;a++) for(int b=0;b<6;b++) if(b!=a) for(int c=0;c<6;c++) if(c!=a && c!=b){
        idx[a][b][c]=states.size();
        states.push_back({a,b,c});
    }
    int S=states.size(); //120
    vector<array<int,3>> nxt(S);
    vector<array<int,3>> addc(S);
    for(int i=0;i<S;i++){
        auto [a,b,c]=states[i];
        int t=0;
        for(int d=0; d<6; d++) if(d!=a && d!=b && d!=c){
            nxt[i][t]=idx[b][c][d];
            addc[i][t]=d;
            t++;
        }
    }

    auto count_fix_d = [&](int d)->int{
        if(d<4) return 0;
        long long total=0;
        // for each starting triple, count closed walks length d with residue 0
        vector<array<int,11>> dp(S), ndp(S);
        for(int start=0; start<S; start++){
            for(int i=0;i<S;i++) for(int r=0;r<11;r++) dp[i][r]=0;
            dp[start][0]=1;
            for(int step=0; step<d; step++){
                for(int i=0;i<S;i++) for(int r=0;r<11;r++) ndp[i][r]=0;
                for(int i=0;i<S;i++){
                    auto &row=dp[i];
                    for(int r=0;r<11;r++) if(row[r]){
                        int ways=row[r];
                        for(int t=0;t<3;t++){
                            int j=nxt[i][t];
                            int nr=r+addc[i][t];
                            if(nr>=11) nr-=11;
                            int &ref=ndp[j][nr];
                            ref += ways;
                            if(ref>=MOD) ref-=MOD;
                        }
                    }
                }
                dp.swap(ndp);
            }
            total += dp[start][0];
            if(total>=MOD) total-=MOD;
        }
        return (int)total;
    };

    vector<int> divisors={1,2,3,4,5,6,8,10,12,15,20,24,30,40,60,120};
    auto phi = [&](int n){
        int result=n;
        int x=n;
        for(int p=2;p*p<=x;p++) if(x%p==0){
            while(x%p==0) x/=p;
            result -= result/p;
        }
        if(x>1) result -= result/x;
        return result;
    };
    long long rotation_sum=0;
    for(int d: divisors){
        int fix=count_fix_d(d);
        int ph=phi(120/d);
        rotation_sum = (rotation_sum + 1LL*ph*fix)%MOD;
        cerr << "d=" << d << " fix=" << fix << " phi=" << ph << " partial=" << rotation_sum << "\n";
    }
    long long answer = rotation_sum * 808333339LL % MOD; // inv240
    cout << "rotation_sum=" << rotation_sum << "\n";
    cout << "answer=" << answer << "\n";
}
