#include <bits/stdc++.h>
using namespace std;
struct Edge{int u,v;};
int main(){
    vector<Edge> edges;
    int idx[8][8]; memset(idx,-1,sizeof(idx));
    for(int i=0;i<8;i++) for(int j=i+1;j<8;j++){
        idx[i][j]=idx[j][i]=edges.size();
        edges.push_back({i,j});
    }
    int E=edges.size(); //28
    vector<vector<pair<int,int>>> checks(E);
    for(int e=0;e<E;e++){
        auto [u,v]=edges[e];
        for(int w=0;w<8;w++) if(w!=u && w!=v){
            checks[e].push_back({idx[u][w], idx[v][w]});
        }
    }
    // Edge order heuristic: sort by how many triangles with earlier edges if lex? We'll use static custom by centrality.
    vector<int> order(E);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a,int b){
        auto ea=edges[a], eb=edges[b];
        int sa=ea.u+ea.v, sb=eb.u+eb.v;
        if(sa!=sb) return sa<sb;
        return a<b;
    });

    vector<int> color(E,-1);
    long long ans=0;
    int need[3]={5,9,14};

    function<void(int)> dfs = [&](int pos){
        if(pos==E){
            if(need[0]==0 && need[1]==0 && need[2]==0) ans++;
            return;
        }
        int rem = E-pos;
        if(need[0]<0||need[1]<0||need[2]<0) return;
        if(need[0]+need[1]+need[2] != rem) return;
        int e=order[pos];
        for(int c=0;c<3;c++) if(need[c]>0){
            bool ok=true;
            for(auto [e1,e2]: checks[e]){
                int c1=color[e1], c2=color[e2];
                if(c1==c && c2==c){ ok=false; break; }
            }
            if(!ok) continue;
            color[e]=c; need[c]--;
            dfs(pos+1);
            need[c]++; color[e]=-1;
        }
    };
    dfs(0);
    cout << ans << '\n';
}
