        int e=order[pos];
        for(int c=0;c<3;c++) if(need[c]>0){
            bool ok=true;
            for(auto [e1,e2]: checks[e]){
                int c1=color[e1], c2=color[e2];
                if(c1==c && c2==c){ ok=false; break; }
            }
            if(!ok) continue;
            color[e]=c; need[c]--;
            dfs(pos+1);
            need[c]++; color[e]=-1;
        }
    };
    dfs(0);
    cout << ans << '\n';
}
