        for(int i=0;i<N;i++) if(deg[i]==0){ ok=false; break; }
        if(ok){
            odd_only++;
            unsigned char seen = 1u<<0;
            int stack[8], top=0;
            stack[top++]=0;
            while(top){
                int u=stack[--top];
                unsigned char nbrs = adj[u] & (unsigned char)~seen;
                while(nbrs){
                    unsigned char b = nbrs & (unsigned char)(-((signed char)nbrs));
                    int v = __builtin_ctz((unsigned)b);
                    seen |= b;
                    stack[top++]=v;
                    nbrs ^= b;
                }
            }
            if(seen == (1u<<N)-1) connected++;
        }
        uint32_t c = x & -x;
        uint32_t r = x + c;
        if(r==0) break;
        x = (((r ^ x) >> 2) / c) | r;
    }
    cout << odd_only << ' ' << connected << '\n';
    return 0;
}
